import java.util.*;

public class Main {
    public static void main(String[] args) {
        // Pitfall 1: Overloaded remove on List<Integer>
        List<Integer> list = new ArrayList<>(Arrays.asList(100, 101, 102, 103));
        System.out.println("Initial List: " + list);

        // Remove at index 1 (removes 101)
        Integer removedByIndex = list.remove(1);
        System.out.println("Removed by index 1: " + removedByIndex);
        System.out.println("After index remove: " + list);

        // Remove by value 102 (must box explicitly!)
        boolean removedByVal = list.remove(Integer.valueOf(102));
        System.out.println("Removed value 102? " + removedByVal);
        System.out.println("After value remove: " + list);

        // Pitfall 2: Safe in-place removal with removeIf
        List<String> words = new ArrayList<>(Arrays.asList("apple", "banana", "avocado"));
        words.removeIf(w -> w.startsWith("a"));
        System.out.println("\nAfter removeIf('a'): " + words);
    }
}

